from math import comb

def calculate_M(n, nR):
    nB = n - nR
    # Use 0 if the combination size is less than 3, as comb handles this for Python >= 3.8
    return comb(nR, 3) + comb(nB, 3)

N_values = [4, 5, 6]
results = {}

for n in N_values:
    min_M = float('inf')
    best_split = None
    for nR in range(n // 2 + 1):
        M = calculate_M(n, nR)
        if M < min_M:
            min_M = M
            best_split = (nR, n - nR)
    results[n] = {"min_M": min_M, "best_split": best_split}

print("Results for minimum M:")
print(results)
